  :NEW.id_estado_organizacion := seq_estado_organizacion.NEXTVAL;
END;
/
CREATE SEQUENCE seq_organizacion START WITH 1 NOCACHE;
CREATE OR REPLACE TRIGGER trg_organizacion_id
BEFORE INSERT ON organizacion FOR EACH ROW WHEN (NEW.id_organizacion IS NULL)
BEGIN
  :NEW.id_organizacion := seq_organizacion.NEXTVAL;
END;
